body {
    background-color: white;
    color: black;
    font-family: 'Inter', sans-serif;
    font-size: medium;
    margin: 0;
    padding: 0;
}

.wrapper {
    display: flex;
    flex-direction: column;
    width: 648px;
    margin: 0 auto; 
    padding-top: 20px;
}

#dummy{
    width: 200px;
    height: 200px;
    /* border-radius: 50%;
    border: 5px solid #000;
    overflow: hidden; */
    margin: 0 auto;
    display: flex;
    align-items: center;
    justify-content: center;
}

#dummy img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.navbar{
    display: flex;
    justify-content: space-between;
    align-items: center;
    /* border-bottom: 1px solid #ccc; */
    padding: 10px 0;
}

.title {
    font-size: 2.25rem;
    font-family: 'Inter';
    margin: 1rem;
    padding-left: 1rem;
    text-transform: uppercase;
}

.navbar{
    justify-content: space-between;
    align-items: center;
    text-align: center;
    padding: 10px 0;
}

.navbar-links ul {
    margin: 0;
    padding: 0;
    display: flex;
}

.navbar-links li{
    list-style: none;
    border-radius: 10px;
    padding: 1rem;
    display: block;
    font-style: bold;
    font-size: 1rem;
}

a {
    text-decoration: none;
    color: black;
}

section {
    padding-top: 10px;
}

